def kth(arr, k):
    if len(arr) == 1:
        return arr[0]

    pivot = arr[0]
    below = [x for x in arr if x < pivot]
    above = [x for x in arr if x > pivot]

    num_less = len(below)
    num_lessoreq = num_less + 1  # Include the pivot in the count of elements <= pivot

    if k < num_less:
        return kth(below, k)
    elif k >= num_lessoreq:
        return kth(above, k - num_less - 1)  # Adjust k for the above array
    else:
        return pivot

