def wrap(text, cols):
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols)
        if end == -1:
            end = cols
        line, text = text[:end].rstrip(), text[end:].lstrip()
        lines.append(line)

    if text:  # Add any remaining text as the last line
        lines.append(text.rstrip())

    return lines

